Arrays.stream(Introspector.getBeanInfo(clazz).getPropertyDescriptors()).filter(property -> !members.containsKey(property.getName())).filter(property -> !transients.contains(property.getName())).filter(property -> !(property instanceof IndexedPropertyDescriptor)).filter(property -> !"class".equals(property.getName())).forEach(property -> {
  Method getter=property.getReadMethod();
  Method setter=property.getWriteMethod();
  boolean isTransient=Arrays.stream(new Method[]{getter,setter}).filter(Objects::nonNull).map(method -> method.getAnnotation(Transient.class)).anyMatch(Objects::nonNull);
  if (isTransient) {
    transients.add(property.getName());
    return;
  }
  Column column=Arrays.stream(new Method[]{getter,setter}).filter(Objects::nonNull).map(method -> method.getAnnotation(Column.class)).filter(Objects::nonNull).findFirst().orElse(null);
  members.put(property.getName(),new AnnoMember(clazz,column,property));
}
